import java.util.*;

class Solution {
    public int maxNetworkingTime(int[] start, int[] finish, int k, int eventTime) {
        int n = start.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(start[a], start[b]));
        long[] gaps = new long[n + 1];
        int prev = 0;
        for (int t = 0; t < n; t++) {
            gaps[t] = start[order[t]] - prev;
            prev = finish[order[t]];
        }
        gaps[n] = eventTime - prev;
        int w = Math.min(k + 1, n + 1);
        long cur = 0;
        for (int i = 0; i < w; i++) cur += gaps[i];
        long best = cur;
        for (int i = w; i <= n; i++) {
            cur += gaps[i] - gaps[i - w];
            best = Math.max(best, cur);
        }
        return (int) best;
    }
}
